mapper.select:
select distinct * from( SELECT TEMP.PORTFOLIO_ID AS portfolioId, PP.PORTFOLIO_NAME AS portfolioName, TEMP.SEC_ACCT_ID AS secAcctId, SSAI.SEC_ACCT_NAME AS secAcctName, TEMP.FINPROD_ID AS finprodId, FP.FINPROD_MARKET_ID AS finprodMarketId, FP.FINPROD_ABBR as finprodName, CASE WHEN instr(FP.FINPROD_MARKET_ID,'.') > 0 THEN SUBSTR(FP.FINPROD_MARKET_ID,1,instr(FP.FINPROD_MARKET_ID,'.',-1,1)-1) ELSE FP.FINPROD_MARKET_ID END AS secId, FP.FINPROD_ABBR AS secName, FSCR.SCALE * 100 AS price, NVL(TEMP.AMOUNT, 0) AS positionsNum, NVL(REPO.AMOUNT, 0) AS repoNum, FLOOR(NVL(STD_SEC.AMT, 0) * NVL(FSCR.SCALE, 1)) AS secNum, NVL(TEMP.AMOUNT, 0) - NVL(REPO.AMOUNT, 0) AS canRepoNum, FP.FINPROD_TYPE2 AS finprodType2, FP.TRADE_MARKET AS tradeMarket, SSAI.TRD_ACCT_ID AS acctId, TEMP2.ACCT_NAME AS acctNo, FLOOR(FLOOR(NVL(STD_SEC.AMT, 0) * NVL(FSCR.SCALE, 1)) * NVL(NVL(NVL(NVL(SBMCI.MORE_CONVRATE,SBMCI2.MORE_CONVRATE),NVL(SBMCICP.MORE_CONVRATE,SBMCICP2.MORE_CONVRATE)),0.9), #{MORE_CONVRATE})) as canUseSecNum, row_number() over (partition by TEMP.PORTFOLIO_ID,TEMP.SEC_ACCT_ID,TEMP.FINPROD_ID order by NVL( NVL(SBMCI.START_DATE, SBMCI2.START_DATE), NVL(SBMCICP.START_DATE, SBMCICP2.START_DATE)) desc) rank FROM
( SELECT PSP.CDATE AS CDATE, PSP.PORTFOLIO_ID AS PORTFOLIO_ID , PSP.SEC_ACCT_ID AS SEC_ACCT_ID , PSP.FINPROD_ID AS FINPROD_ID, PSP.BRANCH AS BRANCH, SUM(CASE WHEN PSP.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_05}) THEN NVL(PSP.AMOUNT,0) ELSE -1* NVL(PSP.AMOUNT,0) END) AS AMOUNT FROM PTL_SEC_POSITION PSP INNER JOIN PTL_PORTFOLIO PP ON PSP.PORTFOLIO_ID = PP.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON PP.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
WHERE PSP.BRANCH =0 AND PSP.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_05}, #{POSITION_TYPE_06}) AND PSP.CDATE = #{date} GROUP BY PSP.CDATE, PSP.PORTFOLIO_ID , PSP.SEC_ACCT_ID, PSP.FINPROD_ID, PSP.BRANCH ) TEMP
LEFT JOIN ( SELECT PSP.CDATE AS CDATE, PSP.PORTFOLIO_ID AS PORTFOLIO_ID , PSP.SEC_ACCT_ID AS SEC_ACCT_ID , PSP.FINPROD_ID AS FINPROD_ID, PSP.BRANCH AS BRANCH, SUM(NVL(PSP.AMOUNT,0)) AS AMOUNT FROM PTL_SEC_POSITION PSP INNER JOIN PTL_PORTFOLIO PP ON PSP.PORTFOLIO_ID = PP.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON PP.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
WHERE PSP.BRANCH =0 AND PSP.HODING_TYPE IN (#{POSITION_TYPE_04}) AND PSP.CDATE = #{date} GROUP BY PSP.CDATE, PSP.PORTFOLIO_ID , PSP.SEC_ACCT_ID, PSP.FINPROD_ID, PSP.BRANCH ) REPO ON TEMP.PORTFOLIO_ID = REPO.PORTFOLIO_ID AND TEMP.SEC_ACCT_ID = REPO.SEC_ACCT_ID AND TEMP.FINPROD_ID = REPO.FINPROD_ID AND TEMP.BRANCH = REPO.BRANCH AND TEMP.CDATE = REPO.CDATE INNER JOIN FIN_PRODUCT FP ON TEMP.FINPROD_ID = FP.FINPROD_ID AND FP.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} LEFT JOIN PTL_PORTFOLIO PP ON TEMP.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON TEMP.SEC_ACCT_ID = SSAI.SEC_ACCT_ID LEFT JOIN (select distinct pci.ACCT_NO,sci.ACCT_NAME, T.CUSTOMER_ID from STL_CAPACCT_INFO sci LEFT JOIN PTL_CAPACCT_INFO pci ON pci.ACCT_NO = sci.ACCT_NO AND pci.CCY = sci.CCY LEFT JOIN(select msd.SALE_DEPID SALE_DEPID, mci.CUSTOMER_ID from mst_sale_department msd left join mst_customer_info mci on mci.CUSTOMER_ID = msd.BROKER_ID where mci.IS_BROKER = 'Y' ) T on T.SALE_DEPID = sci.OWN_DEPT where pci.ACCT_TYPE = 'A07')TEMP2 ON SSAI.TRD_ACCT_ID = TEMP2.ACCT_NO LEFT JOIN (SELECT BROKER_ID, FINPROD_ID,
ACCT_NO,
START_DATE, END_DATE, MORE_CONVRATE FROM STD_BOND_MORE_CONVRATE_INFO WHERE END_DATE IS NOT NULL AND to_date(START_DATE,'yyyy-MM-dd') <= #{date} AND to_date(END_DATE,'yyyy-MM-dd') >= #{date} ) SBMCI
ON TEMP2.CUSTOMER_ID = SBMCI.BROKER_ID AND (TEMP.FINPROD_ID = SBMCI.FINPROD_ID or SSAI.TRD_ACCT_ID = SBMCI.ACCT_NO)
LEFT JOIN (SELECT BROKER_ID, FINPROD_ID,
ACCT_NO,
START_DATE, END_DATE, MORE_CONVRATE FROM STD_BOND_MORE_CONVRATE_INFO WHERE END_DATE IS NULL AND to_date(START_DATE,'yyyy-MM-dd') <= #{date} ) SBMCI2
ON TEMP2.CUSTOMER_ID = SBMCI2.BROKER_ID AND (TEMP.FINPROD_ID = SBMCI2.FINPROD_ID or SSAI.TRD_ACCT_ID = SBMCI2.ACCT_NO)
LEFT JOIN (SELECT BROKER_ID, FINPROD_ID,
ACCT_NO,
START_DATE, END_DATE, MORE_CONVRATE FROM STD_BOND_MORE_CONVRATE_INFO WHERE END_DATE IS NOT NULL AND to_date(START_DATE,'yyyy-MM-dd') <= #{date} AND to_date(END_DATE,'yyyy-MM-dd') >= #{date} ) SBMCICP
ON ('BROKER' = SBMCICP.FINPROD_ID or 'BROKER' = SBMCICP.ACCT_NO) AND TEMP2.CUSTOMER_ID = SBMCICP.BROKER_ID
LEFT JOIN (SELECT BROKER_ID, FINPROD_ID,
ACCT_NO,
START_DATE, END_DATE, MORE_CONVRATE FROM STD_BOND_MORE_CONVRATE_INFO WHERE END_DATE IS NULL AND to_date(START_DATE,'yyyy-MM-dd') <= #{date} ) SBMCICP2
ON ('BROKER' = SBMCICP2.FINPROD_ID or 'BROKER' = SBMCICP2.ACCT_NO) AND TEMP2.CUSTOMER_ID = SBMCICP2.BROKER_ID
INNER JOIN FIN_STDSEC_CONVERSE_RADIO FSCR ON FSCR.FINPROD_ID = TEMP.FINPROD_ID AND FSCR.BRANCH = TEMP.BRANCH AND FSCR.VDATE <= #{date} AND FSCR.MDATE >= #{date} LEFT JOIN ( SELECT TSF.PORTFOLIO_ID, TSF.SEC_ACCT_ID, TSFD.FINPROD_ID, TSFD.BRANCH,
SUM(CASE WHEN TSF.PS = #{LIBRARY_DIRECTION_01} THEN NVL(TSFD.AMT, 0) ELSE -1 * NVL(TSFD.AMT, 0) * NVL(mzData.mzValue, 100) / 100 END) AMT
FROM ( SELECT PORTFOLIO_ID, SEC_ACCT_ID, PS, SEQNO FROM TRD_STASEC_FLOW WHERE CDATE <= #{date}
) TSF INNER JOIN ( SELECT SEQNO, FINPROD_ID, BRANCH, AMT FROM TRD_STASEC_FLOW_DETAIL
) TSFD ON TSFD.SEQNO = TSF.SEQNO
left join ( SELECT t1.FINPROD_ID, t1.BRANCH, 100 - NVL(SUM(NVL(t1.PRIN_AMT, 0)), 0) as mzValue from FIN_CASH_PLAN t1 WHERE t1.FINPROD_TYPE2 = 'F01' and t1.CASH_TYPE in ('02', '03') and t1.MDATE <= #{date,jdbcType=DATE} group by t1.FINPROD_ID, t1.BRANCH ) mzData on TSFD.FINPROD_ID = mzData.FINPROD_ID and TSFD.BRANCH = mzData.BRANCH
GROUP BY TSF.PORTFOLIO_ID, TSF.SEC_ACCT_ID, TSFD.FINPROD_ID, TSFD.BRANCH ) STD_SEC ON TEMP.PORTFOLIO_ID = STD_SEC.PORTFOLIO_ID AND TEMP.SEC_ACCT_ID = STD_SEC.SEC_ACCT_ID AND TEMP.FINPROD_ID = STD_SEC.FINPROD_ID AND TEMP.BRANCH = STD_SEC.BRANCH WHERE FP.TRADE_MARKET IN (#{TRADE_PLACE_03}, #{TRADE_PLACE_04}) AND TEMP.AMOUNT > 0
AND FP.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}
AND TEMP.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
AND FP.FINPROD_MARKET_ID = #{finprodMarketId,jdbcType=VARCHAR}
AND TEMP.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
) a left join SYS_DATADICT_LIST sdl1 on a.tradeMarket=sdl1.ITEM_CODE and sdl1.DICT_CODE='TRADE_PLACE' where rank = 1
order by ${sort} ${direction}

select distinct * from( SELECT TEMP.PORTFOLIO_ID AS portfolioId, PP.PORTFOLIO_NAME AS portfolioName, TEMP.SEC_ACCT_ID AS secAcctId, SSAI.SEC_ACCT_NAME AS secAcctName, TEMP.FINPROD_ID AS finprodId, FP.FINPROD_MARKET_ID AS finprodMarketId, FP.FINPROD_ABBR as finprodName, CASE WHEN instr(FP.FINPROD_MARKET_ID,'.') > 0 THEN SUBSTR(FP.FINPROD_MARKET_ID,1,instr(FP.FINPROD_MARKET_ID,'.',-1,1)-1) ELSE FP.FINPROD_MARKET_ID END AS secId, FP.FINPROD_ABBR AS secName, floor(NVL(TEMP.secNum, 0)/100) AS secNum, NVL(TEMP.canRepoNum, 0) AS canRepoNum, FP.FINPROD_TYPE2 AS finprodType2, FP.TRADE_MARKET AS tradeMarket, SSAI.TRD_ACCT_ID AS acctId, TEMP2.ACCT_NAME AS acctNo, (SELECT NVL(FSCR.SCALE,0)*100 from FIN_STDSEC_CONVERSE_RADIO FSCR where FSCR.FINPROD_ID =TEMP.FINPROD_ID AND FSCR.VDATE <= #{date} AND FSCR.MDATE >= #{date} and rownum =1) discountRate
FROM
( SELECT A.CDATE AS CDATE, A.PORTFOLIO_ID AS PORTFOLIO_ID , A.SEC_ACCT_ID AS SEC_ACCT_ID , A.FINPROD_ID AS FINPROD_ID, A.DATE_TYPE AS DATE_TYPE, SUM(NVL(A.secNum,0)) secNum, SUM(NVL(A.canRepoNum,0)) canRepoNum from ( SELECT PSP.CDATE AS CDATE, PSP.PORTFOLIO_ID AS PORTFOLIO_ID , PSP.SEC_ACCT_ID AS SEC_ACCT_ID , PSP.FINPROD_ID AS FINPROD_ID, PSP.DATE_TYPE AS DATE_TYPE, SUM(NVL(PSP.AMOUNT,0)) AS secNum, 0 as canRepoNum FROM PTL_SEC_POSITION_RULE PSP INNER JOIN PTL_PORTFOLIO PP ON PSP.PORTFOLIO_ID = PP.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON PP.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
WHERE PSP.DATE_TYPE =0 AND PSP.HODING_TYPE=#{A_158} AND PSP.CDATE = #{date} GROUP BY PSP.CDATE, PSP.PORTFOLIO_ID , PSP.SEC_ACCT_ID, PSP.FINPROD_ID, PSP.DATE_TYPE union SELECT PSP.CDATE AS CDATE, PSP.PORTFOLIO_ID AS PORTFOLIO_ID , PSP.SEC_ACCT_ID AS SEC_ACCT_ID , PSP.FINPROD_ID AS FINPROD_ID, PSP.DATE_TYPE AS DATE_TYPE, 0 AS secNum, 0 as canRepoNum FROM ETR_SEC_POSITION_RULE PSP INNER JOIN PTL_PORTFOLIO PP ON PSP.PORTFOLIO_ID = PP.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON PP.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
WHERE PSP.DATE_TYPE =0 AND PSP.CDATE = #{date} and finprod_id in (select DISTINCT t.finprod_id from FIN_STDSEC_CONVERSE_RADIO t where t.branch = 0 AND t.VDATE <= #{date} AND t.MDATE >= #{date} ) and PSP.finprod_id!='XN_PRODID999' GROUP BY PSP.CDATE, PSP.PORTFOLIO_ID , PSP.SEC_ACCT_ID, PSP.FINPROD_ID, PSP.DATE_TYPE) A GROUP BY A.CDATE, A.PORTFOLIO_ID , A.SEC_ACCT_ID, A.FINPROD_ID, A.DATE_TYPE ) TEMP INNER JOIN FIN_PRODUCT FP ON TEMP.FINPROD_ID = FP.FINPROD_ID AND FP.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} LEFT JOIN PTL_PORTFOLIO PP ON TEMP.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON TEMP.SEC_ACCT_ID = SSAI.SEC_ACCT_ID LEFT JOIN (select distinct pci.ACCT_NO,sci.ACCT_NAME, T.CUSTOMER_ID from STL_CAPACCT_INFO sci LEFT JOIN PTL_CAPACCT_INFO pci ON pci.ACCT_NO = sci.ACCT_NO AND pci.CCY = sci.CCY LEFT JOIN(select msd.SALE_DEPID SALE_DEPID, mci.CUSTOMER_ID from mst_sale_department msd left join mst_customer_info mci on mci.CUSTOMER_ID = msd.BROKER_ID where mci.IS_BROKER = 'Y' ) T on T.SALE_DEPID = sci.OWN_DEPT where pci.ACCT_TYPE = 'A07')TEMP2 ON SSAI.TRD_ACCT_ID = TEMP2.ACCT_NO WHERE FP.TRADE_MARKET IN (#{TRADE_PLACE_03}, #{TRADE_PLACE_04})
AND FP.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}
AND TEMP.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
AND FP.FINPROD_MARKET_ID = #{finprodMarketId,jdbcType=VARCHAR}
AND TEMP.FINPROD_ID in
#{item, jdbcType=VARCHAR}
) a left join SYS_DATADICT_LIST sdl1 on a.tradeMarket=sdl1.ITEM_CODE and sdl1.DICT_CODE='TRADE_PLACE' where 1=1
